//! 🧪️ Native UTF8 copying and exact cancellation retain the neutral diagnostic corpus.
fn observe_backing<T>(work: impl FnOnce() -> T) -> (T, usize, usize) { let (output, heap) = semio_framework_trace::observe_heap_allocations_on_this_thread(work); (output, heap.requested_bytes, heap.released_bytes) }
use super::*;
fn close(cursor:&mut MessageCopyCursor){let(_,allocated,released)=observe_backing(||cursor.begin_close());assert_eq!((allocated,released),(0,0));let(step,allocated,released)=observe_backing(||cursor.close_step(RetainedCloneGrant::default()).unwrap());assert_eq!((allocated,released),(0,0));assert_eq!(step.progress(),Default::default());for _ in 0..100000{if cursor.terminal_is_empty(){return;}let((copy,release,depth),allocated,released)=observe_backing(||(cursor.next_close_copy_byte_demand().unwrap(),cursor.next_close_release_byte_demand().unwrap(),cursor.next_close_depth_demand().unwrap()));assert_eq!((allocated,released),(0,0));let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:release,maximum_depth:depth};for short in [RetainedCloneGrant {maximum_depth:depth.saturating_sub(1),..grant},RetainedCloneGrant {maximum_copy_bytes:copy.saturating_sub(1),..grant},RetainedCloneGrant {maximum_release_bytes:release.saturating_sub(1),..grant}]{if short!=grant{let(step,allocated,released)=observe_backing(||cursor.close_step(short).unwrap());assert_eq!((allocated,released),(0,0));assert_eq!(step.progress(),Default::default());}}let(step,allocated,released)=observe_backing(||cursor.close_step(grant).unwrap());assert_eq!(allocated,0,"closure cannot allocate an ungranted scaffold");assert!(step.progress().fits(grant));assert_eq!(released,step.progress().released_bytes);}panic!("message copy exact close must terminate");}
#[test]
fn cooperative_message_copy_obeys_the_neutral_law(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let source=MutationMessage::fatal(row["code"].as_str().unwrap().to_owned(),row["message"].as_str().unwrap()).at(row["target"].as_array().unwrap().iter().map(|segment|segment.as_str().unwrap().to_owned()));for bytes in law["byteGrants"].as_array().unwrap(){let(mut cursor,allocated,released)=observe_backing(MessageCopyCursor::new);assert_eq!((allocated,released),(0,0));let mut turns=0;loop{turns+=1;assert!(turns<100000);let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_copy_byte_demand(&source).unwrap().max(bytes.as_u64().unwrap()as usize),maximum_capacity_bytes:cursor.next_capacity_byte_demand(&source).unwrap(),maximum_release_bytes:0,maximum_depth:1};let(step,allocated,released)=observe_backing(||cursor.advance(&source,grant).unwrap());assert_eq!(released,0);assert!(step.progress().fits(grant));assert_eq!(allocated,step.progress().retained_capacity_bytes);if matches!(step,RetainedCloneStep::Complete(_)){break;}}assert!(turns>source.target.len());assert_eq!(cursor.take().unwrap(),source);close(&mut cursor);let(_,allocated,released)=observe_backing(||drop(cursor));assert_eq!((allocated,released),(0,0));for cancelled_at in law["cancelAt"].as_array().unwrap(){let mut cancelled=MessageCopyCursor::new();for _ in 0..cancelled_at.as_u64().unwrap(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cancelled.next_copy_byte_demand(&source).unwrap().max(bytes.as_u64().unwrap()as usize),maximum_capacity_bytes:cancelled.next_capacity_byte_demand(&source).unwrap(),maximum_release_bytes:0,maximum_depth:1};cancelled.advance(&source,grant).unwrap();}cancelled.cancel();assert_eq!(cancelled.advance(&source,RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:0,maximum_depth:1}).unwrap().progress(),Default::default());assert!(cancelled.take().is_none());close(&mut cancelled);let(_,allocated,released)=observe_backing(||drop(cancelled));assert_eq!((allocated,released),(0,0));}}}let source=MutationMessage::fatal("mutation.invariant","").at(std::iter::repeat_n(String::new(),law["emptySegments"]["count"].as_u64().unwrap()as usize));let mut cursor=MessageCopyCursor::new();let accepted=cursor.advance(&source,RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:law["capacityGrant"].as_u64().unwrap()as usize,maximum_release_bytes:0,maximum_depth:1}).is_ok();assert_eq!(accepted,law["emptySegments"]["accepted"].as_bool().unwrap());close(&mut cursor);eprintln!("[DEBUG] messagecopy neutral UTF8/structural demand, cancellation, emptytarget refusal and exact three-axis depth closure retained");}
